Lemma gstep fx R R' M (pc pc2 : Z) (pcw : word) (W : bv 32) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W ->
  RiscvSemantics.step RSEGS (mkst R (Z_to_bv 64 pc) M (seg_rom RSEGS)) = MachineOk (mkst R' pcw M (seg_rom RSEGS)) ->
  pcw = Z_to_bv 64 pc2 ->
