Definition rq (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 (sp - 112) /\ getr Ri (reg 8) = Z_to_bv 64 p /\ getr Ri (reg 9) = Z_to_bv 64 ov /\ getr Ri (reg 18) = Z_to_bv 64 (p + 8)
