Definition rql (Ri : bvmap 5 word) : Prop :=
  getr Ri (reg 2) = Z_to_bv 64 (sp - 112) /\ getr Ri (reg 9) = Z_to_bv 64 (ov + 8) /\ getr Ri (reg 19) = Z_to_bv 64 ((ov + 8) / 8 + SBL) /\ getr Ri (reg 21) = Z_to_bv 64 SBL /\ csl Ri.
Lemma rql_call Ra Rb : regs_preserved Ra Rb -> rql Ra -> rql Rb.
Proof.
