(* [comment removed for export] *)
Lemma tailE (fxq : FPState) Rq Mq mdq LKq Awq crq kq w c :
  CINV Mq mdq LKq Awq crq kq w w -> w = hdr_str n + n -> rql Rq ->
  getr Rq (reg 8) = Z_to_bv 64 c -> getr Rq (reg 20) = Z_to_bv 64 c -> 1 <= c < 2 ^ 47 -> getr Rq (reg 18) = Z_to_bv 64 1 ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq NEXT Mq mdq) K.
Proof.
