Lemma loop (j : nat) : forall (fxq : FPState) Rq Mq mdq LKq Awq crq kq w,
  (1 <= j)%nat -> Z.of_nat j <= n ->
  CINV Mq mdq LKq Awq crq kq w w -> w + Z.of_nat j = hdr_str n + n -> 0 <= w -> rql Rq ->
  getr Rq (reg 8) = Z_to_bv 64 (d + (n - Z.of_nat j)) -> getr Rq (reg 20) = Z_to_bv 64 (d + (n - Z.of_nat j)) -> getr Rq (reg 18) = Z_to_bv 64 (Z.of_nat j) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq HEAD Mq mdq) K.
Proof.
