(* [comment removed for export] *)
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Lemma BODY (fx2 : FPState) R2 :
  GM BX0 M2 model2 LK2 Aw cr -> L5SAR.ek L ar (BX0 ++ LBXg) FF sp SCR [] M M2 ->
  getr R2 (reg 2) = Z_to_bv 64 spc -> getr R2 (reg 3) = getr R (reg 3) -> getr R2 (reg 4) = getr R (reg 4) ->
  getr R2 (reg 8) = Z_to_bv 64 sp -> getr R2 (reg 9) = Z_to_bv 64 spc -> getr R2 (reg 10) = Z_to_bv 64 F ->
  getr R2 (reg 20) = Z_to_bv 64 ov -> getr R2 (reg 21) = Z_to_bv 64 0 -> getr R2 (reg 22) = Z_to_bv 64 oec -> getr R2 (reg 23) = Z_to_bv 64 p -> getr R2 (reg 27) = Z_to_bv 64 SBL ->
